package com.agriconnect.notification;import io.micrometer.core.instrument.*;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;import java.util.*;import org.slf4j.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import org.springframework.web.servlet.HandlerMapping;@Component class ObservabilityFilter extends OncePerRequestFilter{private static final Logger log=LoggerFactory.getLogger(ObservabilityFilter.class);private final MeterRegistry m;ObservabilityFilter(MeterRegistry m){this.m=m;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException{long n=System.nanoTime();String t=Optional.ofNullable(r.getHeader("X-Trace-Id")).filter(x->!x.isBlank()).orElseGet(()->UUID.randomUUID().toString());MDC.put("traceId",t);p.setHeader("X-Trace-Id",t);try{c.doFilter(r,p);}finally{String e=String.valueOf(Optional.ofNullable(r.getAttribute(HandlerMapping.BEST_MATCHING_PATTERN_ATTRIBUTE)).orElse(r.getRequestURI()));long d=System.nanoTime()-n;m.counter("agriconnect.http.requests","service","notification-service","method",r.getMethod(),"endpoint",e,"status",String.valueOf(p.getStatus())).increment();m.timer("agriconnect.http.duration","service","notification-service","endpoint",e).record(d,java.util.concurrent.TimeUnit.NANOSECONDS);var a=SecurityContextHolder.getContext().getAuthentication();log.info("{\"service\":\"notification-service\",\"traceId\":\"{}\",\"userId\":\"{}\",\"endpoint\":\"{}\",\"status\":{},\"durationMs\":{}}",t,a==null?"anonymous":a.getName(),e,p.getStatus(),d/1_000_000);MDC.remove("traceId");}}}
